                id
                name
                creator
                coverArt {
                    url
                }
                genre {
                    name
                }
                description
                downloadUrl
            }
        }
    `;
    const data = await graphqlRequest(query);
    return data.samplePacks.map((p: any) => ({
        ...p,
        genre: Array.isArray(p.genre) ? p.genre.map((g: any) => g.name) : []
