async function graphqlRequest(query: string, variables: Record<string, any> = {}) {
    const headers = {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${AUTH_TOKEN}`,
    };
    const response = await fetch(API_URL, {
        method: 'POST',
        headers,
        body: JSON.stringify({ query, variables }),
    });
    const json = await response.json();
    if (json.errors) throw new Error(json.errors[0].message);
    return json.data;
}

export const getGenres = async (): Promise<Genre[]> => {
    const query = `query { genres(orderBy: order_ASC) { id name slug } }`;
    const data = await graphqlRequest(query);
    return data.genres;
};

export const getSamplePacks = async (genreSlug?: string): Promise<SamplePack[]> => {
    const whereClause = genreSlug && genreSlug !== 'All' ? `(where: { genre_some: { name: "${genreSlug}" } })` : '';

    // Exact format requested: id, name, creator, coverArt { url }, genre, description, downloadUrl
    const query = `
        query GetSamplePacks {
            samplePacks${whereClause} {
                id
                name
                creator
                coverArt {
                    url
                }
                genre {
                    name
                }
                description
                downloadUrl
                featured
                slug
            }
        }
    `;
    const data = await graphqlRequest(query);
    return data.samplePacks.map((p: any) => ({
        ...p,
        genre: Array.isArray(p.genre) ? p.genre.map((g: any) => g.name) : []
    }));
};

export const getPresets = async (): Promise<Preset[]> => {
    const query = `
        query {
            presets {
                id name slug creator description downloadUrl pluginCompatibility
                coverArt { url }
