async function graphqlRequest(query: string, variables: Record<string, any> = {}) {
    const headers = {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${AUTH_TOKEN}`,
    };
    try {
        const response = await fetch(API_URL, {
            method: 'POST',
            headers,
            body: JSON.stringify({ query, variables }),
        });
        const json = await response.json();
        if (json.errors) {
            // Log the error but don't throw to allow fallbacks
            console.warn('GraphQL Warning:', json.errors[0].message);
            return null;
        }
        return json.data;
    } catch (e) {
        console.error('Network Error:', e);
        return null;
    }
}

export const getGenres = async (): Promise<Genre[]> => {
    const query = `query { genres(orderBy: order_ASC) { id name slug } }`;
    const data = await graphqlRequest(query);
    return data?.genres || [];
};

export const getSamplePacks = async (genreSlug?: string): Promise<SamplePack[]> => {
    const whereClause = genreSlug && genreSlug !== 'All' ? `(where: { genre_contains_some: ["${genreSlug}"] })` : '';

    // Fixed: 'genre' is queried as a scalar (String) to fix "[line: 1] field 'name' is not defined in 'String'"
    const query = `
        query GetSamplePacks {
            samplePacks${whereClause} {
                id
                name
                creator
                coverArt {
                    url
                }
                genre
                description
                downloadUrl
                featured
                slug
            }
        }
    `;
    const data = await graphqlRequest(query);
    if (!data?.samplePacks) return [];

    return data.samplePacks.map((p: any) => ({
        ...p,
        // Ensure genre is always an array of strings
        genre: Array.isArray(p.genre) ? p.genre : (p.genre ? [p.genre] : [])
    }));
};

export const getPresets = async (): Promise<Preset[]> => {
    const query = `
        query {
            presets {
                id name slug creator description downloadUrl pluginCompatibility
                coverArt { url }
                genre
            }
        }
    `;
    const data = await graphqlRequest(query);
    if (!data?.presets) return [];

    return data.presets.map((p: any) => ({
        ...p,
        genre: Array.isArray(p.genre) ? p.genre : (p.genre ? [p.genre] : [])
    }));
};

