export const addComment = async (entityId: string, authorName: string, text: string): Promise<Comment> => {
    const mutation = `
        mutation CreateComment($entityId: String!, $authorName: String!, $text: String!) {
            createComment(data: { entityId: $entityId, authorName: $authorName, text: $text }) {
                id authorName text createdAt
            }
        }
    `;
    const data = await graphqlRequest(mutation, { entityId, authorName, text });
    if (data?.createComment) {
        await graphqlRequest(`mutation { publishComment(where: { id: "${data.createComment.id}" }, to: PUBLISHED) { id } }`);
        return data.createComment;
    }
    throw new Error("Failed to add comment");
};

export const sendContactMessage = async (name: string, email: string, message: string) => {
    const mutation = `
        mutation {
            createContactMessage(data: { name: "${name}", email: "${email}", message: "${message}" }) { id }
        }
    `;
    const data = await graphqlRequest(mutation);
    if (data?.createContactMessage) {
        await graphqlRequest(`mutation { publishContactMessage(where: { id: "${data.createContactMessage.id}" }, to: PUBLISHED) { id } }`);
        return true;
    }
    return false;
};

