import React, { useState, useEffect } from 'react';
import { SamplePack, Comment } from '../types';
import { getComments, addComment } from '../services/graphqlService';
import Button from './Button';
import Input from './Input';
import { CloseIcon } from '../constants';

interface ContentModalProps {
  item: SamplePack;
  onClose: () => void;
}

const ContentModal: React.FC<ContentModalProps> = ({ item, onClose }) => {
  const [comments, setComments] = useState<Comment[]>([]);
  const [newComment, setNewComment] = useState({ name: '', text: '' });
  const [loading, setLoading] = useState(false);
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    setLoading(true);
    getComments(item.slug).then(setComments).finally(() => setLoading(false));

    const handleEsc = (e: KeyboardEvent) => e.key === 'Escape' && onClose();
    window.addEventListener('keydown', handleEsc);
    document.body.style.overflow = 'hidden';
    return () => {
      window.removeEventListener('keydown', handleEsc);
      document.body.style.overflow = 'unset';
    };
  }, [item.slug, onClose]);

  const handleCommentSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newComment.text.trim()) return;
    setSubmitting(true);
    try {
      const name = newComment.name.trim() || 'Anonymous';
      const res = await addComment(item.slug, name, newComment.text);
      setComments([res, ...comments]);
      setNewComment({ name: '', text: '' });
    } catch (err) {
      console.error(err);
    } finally {
      setSubmitting(false);
    }
  };

  const coverUrl = item.coverArt?.[0]?.url || 'https://via.placeholder.com/600';

  return (
    <div 
      className="fixed inset-0 z-[60] flex items-center justify-center p-4 sm:p-6 bg-brand-dark/95 backdrop-blur-xl animate-in fade-in duration-300"
      onClick={onClose}
    >
      <div 
        className="relative bg-brand-panel-light border border-white/10 w-full max-w-5xl max-h-[95vh] sm:max-h-[90vh] rounded-[2.5rem] shadow-2xl overflow-hidden flex flex-col md:flex-row animate-in zoom-in-95 duration-300"
        onClick={e => e.stopPropagation()}
      >
        {/* Close Button */}
        <button 
          onClick={onClose} 
          className="absolute top-4 right-4 sm:top-6 sm:right-6 p-2 bg-brand-dark/40 hover:bg-brand-dark/60 backdrop-blur-md rounded-full text-white transition-all z-20 border border-white/10"
        >
          <CloseIcon className="w-6 h-6" />
        </button>

        {/* Image Section */}
        <div className="w-full md:w-1/2 lg:w-5/12 shrink-0 bg-brand-dark/20 relative">
          <div className="aspect-square md:h-full w-full">
            <img 
              src={coverUrl} 
              alt={item.name} 
              className="w-full h-full object-cover" 
            />
            <div className="absolute inset-0 bg-gradient-to-t from-brand-dark/60 to-transparent md:hidden" />
          </div>
        </div>

        {/* Content Section */}
        <div className="flex-grow p-6 sm:p-10 md:p-12 overflow-y-auto custom-scrollbar flex flex-col">
          <div className="mb-8">
            <div className="flex flex-wrap gap-2 mb-4">
              {(item.genre as string[]).map(g => (
                <span key={g} className="px-3 py-1 bg-brand-cyan/10 border border-brand-cyan/20 rounded-full text-[10px] font-black text-brand-cyan uppercase tracking-widest">{g}</span>
              ))}
            </div>
            <h2 className="text-3xl sm:text-4xl lg:text-5xl font-black mb-2 text-white leading-tight">{item.name}</h2>
            <p className="text-brand-muted text-lg font-bold">Released by <span className="text-white">{item.creator}</span></p>

            <div className="mt-6 bg-white/5 p-6 rounded-2xl border border-white/5">
               <p className="text-brand-muted leading-relaxed text-base sm:text-lg">{item.description}</p>
            </div>
          </div>

          {/* Download Action */}
          <div className="mb-10">
            <a href={item.downloadUrl} target="_blank" rel="noopener noreferrer" className="block">
              <Button size="lg" className="w-full py-5 text-xl rounded-2xl shadow-xl shadow-brand-cyan/20">
                Download Free Pack
              </Button>
            </a>
          </div>

          {/* Comments Section */}
          <div className="pt-8 border-t border-white/5 mt-auto">
            <h3 className="text-xl font-black mb-6 flex items-center gap-3 text-white">
              Discussion 
              <span className="text-xs bg-white/10 px-2 py-0.5 rounded-md text-brand-muted">{comments.length}</span>
            </h3>

            <form onSubmit={handleCommentSubmit} className="space-y-4 mb-8">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="flex-grow">
                  <input 
                    type="text"
                    placeholder="Display Name" 
                    className="w-full px-4 py-3 bg-brand-dark/50 border border-white/10 rounded-xl text-white placeholder-white/20 focus:outline-none focus:ring-2 focus:ring-brand-cyan transition text-sm"
                    value={newComment.name} 
                    onChange={e => setNewComment({...newComment, name: e.target.value})}
                  />
                </div>
                <div className="flex gap-2">
                  <input 
                    type="text"
                    placeholder="Write a comment..." 
                    className="flex-grow px-4 py-3 bg-brand-dark/50 border border-white/10 rounded-xl text-white placeholder-white/20 focus:outline-none focus:ring-2 focus:ring-brand-cyan transition text-sm"
                    value={newComment.text} 
                    onChange={e => setNewComment({...newComment, text: e.target.value})}
                    required
                  />
                  <Button type="submit" isLoading={submitting} className="rounded-xl px-6">Post</Button>
                </div>
              </div>
            </form>

            <div className="space-y-4 max-h-64 overflow-y-auto pr-2 custom-scrollbar">
              {loading ? (
                <div className="space-y-3">
                  {[1,2].map(i => <div key={i} className="h-20 bg-white/5 animate-pulse rounded-2xl"></div>)}
                </div>
              ) : comments.length > 0 ? (
                comments.map(c => (
                  <div key={c.id} className="bg-white/5 p-5 rounded-2xl border border-white/5">
                    <div className="flex justify-between items-center mb-2">
                      <span className="font-black text-brand-cyan text-xs uppercase tracking-wider">{c.authorName}</span>
                      <span className="text-[10px] text-brand-muted font-bold">{new Date(c.createdAt).toLocaleDateString()}</span>
                    </div>
                    <p className="text-sm text-brand-text leading-relaxed">{c.text}</p>
                  </div>
                ))
              ) : (
                <div className="text-center py-10 bg-white/5 rounded-2xl border border-dashed border-white/10">
                  <p className="text-brand-muted italic text-sm">No comments yet. Be the first to shout out!</p>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ContentModal;

