async function graphqlRequest(query: string, variables: Record<string, any> = {}) {
    const headers = {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${AUTH_TOKEN}`,
    };
    try {
        const response = await fetch(API_URL, {
            method: 'POST',
            headers,
            body: JSON.stringify({ query, variables }),
        });
        const json = await response.json();
        if (json.errors) {
            console.error('Hygraph GraphQL Error:', json.errors.map((e: any) => e.message).join(', '));
            return { errors: json.errors };
        }
        return { data: json.data };
    } catch (e) {
        console.error('Network Error:', e);
        return { errors: [{ message: 'Network request failed' }] };
    }
}

const normalizeContent = (item: any) => {
    if (!item) return null;
    return {
        ...item,
        coverArt: Array.isArray(item.coverArt) ? item.coverArt : (item.coverArt ? [item.coverArt] : []),
        genre: Array.isArray(item.genre) ? item.genre : (item.genre ? [item.genre] : [])
    };
};

export const getGenres = async (): Promise<Genre[]> => {
    const query = `query { genres(orderBy: order_ASC) { id name slug } }`;
    const response = await graphqlRequest(query);
    return response.data?.genres || [];
};

export const getSamplePacks = async (genreSlug?: string): Promise<SamplePack[]> => {
    const whereClause = genreSlug && genreSlug !== 'All' ? `(where: { genre_contains_some: ["${genreSlug}"] })` : '';
    const query = `
        query GetSamplePacks {
            samplePacks${whereClause} {
                id name creator genre description downloadUrl featured slug
                coverArt { url }
            }
        }
    `;
    const response = await graphqlRequest(query);
    if (!response.data?.samplePacks) return [];
    return response.data.samplePacks.map(normalizeContent);
};

export const getPresets = async (): Promise<Preset[]> => {
    const query = `
        query {
            presets {
                id name slug creator description downloadUrl pluginCompatibility genre
                coverArt { url }
            }
        }
    `;
    const response = await graphqlRequest(query);
    if (!response.data?.presets) return [];
    return response.data.presets.map(normalizeContent);
};

export const getPlugins = async (): Promise<Plugin[]> => {
    const query = `
        query {
            plugins {
                id name slug developer description downloadUrl
                coverArt { url }
            }
        }
    `;
    const response = await graphqlRequest(query);
    if (!response.data?.plugins) return [];
