        query GetComments($entityId: String!) {
            comments(where: { entityId: $entityId }, orderBy: createdAt_DESC) {
                id name text createdAt
            }
        }
    `;
    const response = await graphqlRequest(query, { entityId });
    const serverComments = response.data?.comments || [];
    const localComments = LOCAL_COMMENTS[entityId] || [];
    return [...localComments, ...serverComments].sort((a, b) => 
        new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
    );
};

export const addComment = async (entityId: string, authorName: string, text: string): Promise<Comment> => {
    // FIX: Changed 'authorName' to 'name' in mutation data
    const mutation = `
        mutation CreateComment($entityId: String!, $name: String!, $text: String!) {
            createComment(data: { entityId: $entityId, name: $name, text: $text }) {
                id name text createdAt
            }
        }
    `;
    const response = await graphqlRequest(mutation, { entityId, name: authorName, text });

    if (response.data?.createComment) {
        try {
            await graphqlRequest(`mutation { publishComment(where: { id: "${response.data.createComment.id}" }, to: PUBLISHED) { id } }`);
        } catch(e) {}
        return response.data.createComment;
    }

    const fallbackComment: Comment = {
        id: `local-${Date.now()}`,
        entityId,
        name: authorName,
        text,
        createdAt: new Date().toISOString()
    };
    if (!LOCAL_COMMENTS[entityId]) LOCAL_COMMENTS[entityId] = [];
    LOCAL_COMMENTS[entityId].unshift(fallbackComment);
    return fallbackComment;
};

export const sendContactMessage = async (name: string, email: string, message: string) => {
    const mutation = `
        mutation CreateContactMessage($name: String!, $email: String!, $message: String!) {
            createContactMessage(data: { name: $name, email: $email, message: $message }) { 
                id 
            }
        }
    `;
    const response = await graphqlRequest(mutation, { name, email, message });

    if (response.data?.createContactMessage) {
        try {
            await graphqlRequest(`mutation { publishContactMessage(where: { id: "${response.data.createContactMessage.id}" }, to: PUBLISHED) { id } }`);
        } catch(e) {}
        return true;
    }
    return true; 
};

import React, { useState, useEffect } from 'react';
import { SamplePack, Comment } from '../types';
import { getComments, addComment } from '../services/graphqlService';
import Button from './Button';
import { CloseIcon } from '../constants';

interface ContentModalProps {
  item: SamplePack;
  onClose: () => void;
}

const ContentModal: React.FC<ContentModalProps> = ({ item, onClose }) => {
  const [comments, setComments] = useState<Comment[]>([]);
  const [newComment, setNewComment] = useState({ name: '', text: '' });
  const [loading, setLoading] = useState(false);
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    setLoading(true);
    getComments(item.slug).then(setComments).finally(() => setLoading(false));

    const handleEsc = (e: KeyboardEvent) => e.key === 'Escape' && onClose();
    window.addEventListener('keydown', handleEsc);
    document.body.style.overflow = 'hidden';
    return () => {
      window.removeEventListener('keydown', handleEsc);
      document.body.style.overflow = 'unset';
    };
  }, [item.slug, onClose]);

  const handleCommentSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newComment.text.trim()) return;
    setSubmitting(true);
    try {
      const name = newComment.name.trim() || 'Anonymous';
      const res = await addComment(item.slug, name, newComment.text);
      setComments([res, ...comments]);
      setNewComment({ name: '', text: '' });
    } catch (err) {
      console.error(err);
    } finally {
      setSubmitting(false);
    }
  };

  const coverUrl = item.coverArt?.[0]?.url || 'https://via.placeholder.com/600';

  return (
    <div 
      className="fixed inset-0 z-[60] flex items-center justify-center p-3 sm:p-6 bg-brand-dark/95 backdrop-blur-xl animate-in fade-in duration-300"
      onClick={onClose}
